const DICTIONARIES = {
  en,
  hi,
  te,
  ta,
  ml,
  kn,
  or,
  bn,
  mr,
  gu,
};

/* ------------------------------------------------------------------ */
/* Store                                                               */
/* ------------------------------------------------------------------ */

const STORAGE_KEY = "salty_lang";
const listeners = new Set();
let snapshot = null;

function readStored() {
  if (typeof window === "undefined") return "en";
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (raw && DICTIONARIES[raw]) return raw;
  } catch {
    // storage blocked — English it is
  }
  return "en";
}

function subscribe(listener) {
  listeners.add(listener);
  if (typeof window !== "undefined") {
    // A second tab (or a second SALTY window on the same phone) switching
    // language should move this one too.
    window.addEventListener("storage", listener);
  }
  return () => {
    listeners.delete(listener);
    if (typeof window !== "undefined") window.removeEventListener("storage", listener);
  };
}

function getSnapshot() {
  if (snapshot === null) snapshot = readStored();
  return snapshot;
}

export function setLanguage(code) {
  try {
    window.localStorage.setItem(STORAGE_KEY, code);
    document.documentElement.lang = code;
  } catch {
    // ignore
  }
  snapshot = code;
  listeners.forEach((listener) => listener());
}

export function useLanguage() {
  return React.useSyncExternalStore(subscribe, getSnapshot, () => "en");
}

/** Fill `{name}` placeholders. */
function interpolate(template, vars) {
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (match, key) =>
    key in vars ? String(vars[key]) : match
  );
}

export function translate(lang, key, vars) {
  const value = DICTIONARIES[lang]?.[key] ?? en[key] ?? key;
  return interpolate(value, vars);
}

/**
 * `t` for the current language, plus the language itself for anything that
 * needs the raw code (speech, `lang` attributes, number formatting).
 */
export function useT() {
  const lang = useLanguage();
  const t = React.useCallback((key, vars) => translate(lang, key, vars), [lang]);
  return { t, lang, language: languageFor(lang) };
}

/* ------------------------------------------------------------------ */
/* Speech                                                              */
/* ------------------------------------------------------------------ */

export function speechSupported() {
  return typeof window !== "undefined" && "speechSynthesis" in window;
}

/**
 * Pick the closest installed voice: an exact locale match first, then any
 * voice for the same language, then whatever the device defaults to. A phone
 * with no Telugu voice will read the Telugu text in its default voice, which
 * is rough but better than silence.
 */
/**
 * Read text out in the language currently selected.
 *
 * Uses the browser's own speech synthesiser, so it needs no network and no
 * key — which matters on a boat. Whether a given Indian language has a voice
 * installed is the device's business; `supported` only reports whether the
 * API exists at all.
 */
export function useSpeech() {
  const { language } = useT();
  const [speaking, setSpeaking] = React.useState(false);
  const pendingSpeakRef = React.useRef(null);
  const supported = React.useSyncExternalStore(
    () => () => {},
    () => speechSupported(),
    () => false
  );

  React.useEffect(() => {
    return () => {
      if (pendingSpeakRef.current !== null) window.clearTimeout(pendingSpeakRef.current);
      if (speechSupported()) window.speechSynthesis.cancel();
    };
  }, []);

  const stop = React.useCallback(() => {
    if (pendingSpeakRef.current !== null) {
      window.clearTimeout(pendingSpeakRef.current);
      pendingSpeakRef.current = null;
    }
    if (!speechSupported()) return;
    window.speechSynthesis.cancel();
    setSpeaking(false);
  }, []);

  const speak = React.useCallback(
    (text) => {
      if (!speechSupported() || !text.trim()) return;
      const synthesiser = window.speechSynthesis;
      synthesiser.cancel();
      // Some mobile browsers leave the synthesiser paused after canceling a
      // previous utterance. Resuming here makes repeated reads reliable.
      synthesiser.resume();

      // `resolveVoice` waits for nothing: by the time a person taps a read
      // button the registry is long since populated. What it does do is fall
      // back to the Indian English voice when the device has none for this
      // language, which is the common case on a Windows machine — five voices,
      // all English. The text is romanised to match, because an English engine
      // handed Telugu script speaks none of it.
      const { voice, spokenLocale, substituted } = resolveVoice(language.speech);
      const spokenText =
        substituted && hasIndicScript(text) ? romanise(text) : text;

      const utterance = new SpeechSynthesisUtterance(spokenText);
      utterance.lang = spokenLocale;
      if (voice) utterance.voice = voice;
      // Slightly slower than default: this is read over engine noise, and
      // slower still when the spelling is romanised rather than native.
      utterance.rate = substituted ? 0.9 : 0.95;
      utterance.onstart = () => setSpeaking(true);
      utterance.onend = () => setSpeaking(false);
      utterance.onerror = () => setSpeaking(false);

      setSpeaking(true);
      // Yield one turn after cancel so Chrome/Safari do not discard the new
      // utterance while the old queue is being flushed.
      pendingSpeakRef.current = window.setTimeout(() => {
        pendingSpeakRef.current = null;
        synthesiser.speak(utterance);
      }, 0);
    },
    [language.speech]
  );

  return { speak, stop, speaking, supported };
}
